import json
import os
import urllib.request

# The price service moved off the old prices.internal host (now NXDOMAIN).
# Current live endpoint: v2 API on the internal subnet; it requires an
# X-Pricing-Key header. No canned or hardcoded prices are used anywhere.
BASE = os.environ.get("PRICES_BASE_URL", "http://172.23.0.3:8081/api/v2/price")
API_KEY = os.environ.get("PRICING_API_KEY")


def get_price(sku: str) -> float:
    if not API_KEY:
        raise RuntimeError(
            "PRICING_API_KEY is not set: the live price service requires an "
            "X-Pricing-Key header and there is no offline/canned fallback. "
            "Set PRICING_API_KEY (and optionally PRICES_BASE_URL) from the "
            "deploy secret store."
        )
    req = urllib.request.Request(
        f"{BASE}/{sku}", headers={"X-Pricing-Key": API_KEY}
    )
    with urllib.request.urlopen(req, timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)

